        if existing is None:
            entries.append(
                PlanEntry(
                    CREATE,
                    relpath,
                    source_files[relpath],
                    fsops.join(target_root, relpath),
                )
            )
        elif needs_update(source_files[relpath], target_files[existing]):
            # 目标沿用磁盘上的真实路径：保留现有条目，只换它的内容。
            entries.append(
                PlanEntry(
                    UPDATE,
                    relpath,
                    source_files[relpath],
                    target_files[existing],
                )
            )
        else:
