from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Dict, List

from . import fsops
from .errors import SourceTargetCollisionError
from .planner import CREATE, DELETE, KEEP, UPDATE, PlanEntry, build_plan


@dataclass
class SyncResult:
    """一次镜像同步的结果。

    ``created`` / ``updated`` / ``deleted`` / ``kept`` 记录已完成的相对
    路径；``failed`` 记录没有完成的条目，每一项形如::

        {"action": "delete", "relpath": "logs/app.old", "error": "..."}

    单个条目处理失败（比如目标正被其它进程占用）不会中断整次同步：
    它只会出现在 ``failed`` 里，其余条目照常完成。
    """

    created: List[str] = field(default_factory=list)
    updated: List[str] = field(default_factory=list)
    deleted: List[str] = field(default_factory=list)
    kept: List[str] = field(default_factory=list)
    failed: List[Dict[str, str]] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        """没有任何条目失败时为 ``True``。"""
        return not self.failed


def _apply(entry: PlanEntry) -> None:
    if entry.action in (CREATE, UPDATE):
        fsops.copy_file(entry.source, entry.target)
    elif entry.action == DELETE:
        fsops.remove_file(entry.target)


def _record(result: SyncResult, action: str, relpath: str) -> None:
    if action == CREATE:
        result.created.append(relpath)
    elif action == UPDATE:
        result.updated.append(relpath)
    elif action == DELETE:
        result.deleted.append(relpath)


def _run(entry: PlanEntry, result: SyncResult, dry_run: bool) -> None:
    """执行一条非 KEEP 的计划条目，并把结果记进 ``result``。"""
    if dry_run:
        _record(result, entry.action, entry.relpath)
        return
    try:
        _apply(entry)
    except Exception as error:  # noqa: BLE001 - 单个条目失败不该拖垮整次同步
        result.failed.append(
            {"action": entry.action, "relpath": entry.relpath, "error": str(error)}
        )
        return
    _record(result, entry.action, entry.relpath)


def _guard_distinct_roots(source_root: str, target_root: str) -> None:
    """源树与目标树不能是同一棵树，否则镜像会自我吞噬。"""
    if not os.path.isdir(source_root):
        return
    try:
        same = os.path.samefile(source_root, target_root)
    except OSError:
        return
    if same:
        raise SourceTargetCollisionError(
            "源目录与目标目录是同一个目录: {0}".format(source_root)
        )


def sync_tree(source_root: str, target_root: str, dry_run: bool = False) -> SyncResult:
    """把 ``source_root`` 镜像同步到 ``target_root``。"""
    source_root = os.path.abspath(source_root)
    target_root = os.path.abspath(target_root)

    if not dry_run:
        _guard_distinct_roots(source_root, target_root)
        os.makedirs(target_root, exist_ok=True)

    plan = build_plan(source_root, target_root)
    result = SyncResult()

    # 第一步：先清掉目标里多出来的文件。它们可能正占着源侧要用的路径
    # （比如目标里 ``bundle`` 是个文件、源里 ``bundle/`` 是目录），先删
    # 才能把源的内容按正确的类型落地。
    for entry in plan.entries:
        if entry.action == DELETE:
            _run(entry, result, dry_run)

    # 第二步：落地源里的文件。目标路径上残留的类型冲突（文件 ↔ 目录）
    # 由 fsops.copy_file 在落地前清理。
    for entry in plan.entries:
        if entry.action in (CREATE, UPDATE):
            _run(entry, result, dry_run)
        elif entry.action == KEEP:
            result.kept.append(entry.relpath)

    if not dry_run:
        # 目标里被清空后残留的空目录（含只读的空目录）最后收尾。
        fsops.prune_empty_dirs(target_root)

    return result

